# Check: Does output[r][c] equal input[some_transform](r,c)?
# Try different transforms:
# - identity: (r,c) -> output[r][c] == input[r][c]? NO (input has many zeros)
# - rotate: (r,c) -> output[r][c] == input[c][r]? Let's check
# - flip: (r,c) -> output[r][c] == input[H-1-r][W-1-c]? Let's check

def check_identity(in_g, out_g):
    m, n = len(in_g), len(in_g[0])
    matches = 0
    for r in range(m):
        for c in range(n):
            if in_g[r][c] != 0 and out_g[r][c] == in_g[r][c]:
                matches += 1
    return matches

def check_transpose(in_g, out_g):
    m, n = len(in_g), len(in_g[0])
    matches = 0
    for r in range(min(m,n)):
        for c in range(min(m,n)):
            if in_g[r][c] != 0 and out_g[c][r] == in_g[r][c]:
                matches += 1
    return matches

def check_flip(in_g, out_g):
    m, n = len(in_g), len(in_g[0])
    matches = 0
    for r in range(m):
        for c in range(n):
            if in_g[r][c] != 0 and out_g[m-1-r][n-1-c] == in_g[r][c]:
                matches += 1
    return matches

def check_rotate(in_g, out_g):
    m, n = len(in_g), len(in_g[0])
    matches = 0
    for r in range(m):
        for c in range(n):
            if in_g[r][c] != 0 and out_g[n-1-c][r] == in_g[r][c]:
                matches += 1
    return matches

